function motif(date,names='',events=[]){const [y,m,d]=date.split('-').map(Number),day=new Date(y,m-1,d,12);const a=y%19,b=Math.floor(y/100),c=y%100,h=(19*a+b-Math.floor(b/4)-Math.floor((b-Math.floor((b+8)/25)+1)/3)+15)%30,l=(32+2*(b%4)+2*Math.floor(c/4)-h-c%4)%7,q=Math.floor((a+11*h+22*l)/451),em=Math.floor((h+l-7*q+114)/31),ed=(h+l-7*q+114)%31+1;const easter=new Date(y,em-1,ed,12),diff=Math.round((day-easter)/86400000);if(diff===0)return 11;if(m===5&&day.getDay()===0&&d>=8&&d<=14)return 18;const christmas=new Date(y,11,25,12),advent=new Date(y,11,25-((christmas.getDay()||7)+21),12);if(day>=advent&&day<christmas&&day.getDay()===0)return 36;const text=[names,...events.map(e=>e.name)].join(' ');if(/Velký pátek|Veľký piatok/i.test(text))return 10;if(/pondělí|pondelok/i.test(text)&&/velikono|veľkono/i.test(text))return 12;if(/velikonoční neděle|veľkonočná nedeľa/i.test(text))return 11;if(/advent/i.test(text))return 36;return dates[date.slice(5)]||0;}
