function install(){if(host)return;host=document.querySelector('.hero');if(!host)return;document.body.classList.add('holiday-editorial');host.querySelector('.calendar-art')?.remove();const dateBox=host.firstElementChild,legacy=document.createElement('div');legacy.hidden=true;legacy.append(...dateBox.childNodes);datePanel=document.createElement('div');datePanel.className='holiday-date-panel';dateDay=document.createElement('div');dateDay.className='holiday-date-day';dateMonth=document.createElement('div');dateMonth.className='holiday-date-month';dateFoot=document.createElement('div');dateFoot.className='holiday-date-foot';datePanel.append(dateDay,dateMonth,dateFoot);dateBox.append(legacy,datePanel);const copy=document.createElement('div');copy.className='holiday-feature-copy';label=document.createElement('div');label.className='holiday-feature-label';title=document.createElement('div');title.className='holiday-feature-title';note=document.createElement('div');note.className='holiday-feature-note';copy.append(label,title,note);art=document.createElement('div');art.className='holiday-feature-art';art.setAttribute('aria-hidden','true');host.append(copy,art);observer=new ResizeObserver(fit);observer.observe(host);observer.observe(host.firstElementChild);root.addEventListener('load',()=>requestAnimationFrame(fit));document.fonts?.ready.then(()=>requestAnimationFrame(fit));}
function fit(){if(!host)return;const size=host.getBoundingClientRect(),unit=parseFloat(getComputedStyle(host).getPropertyValue('--edu-text-label'))||20;const compact=size.height<unit*3||size.width<unit*12||innerWidth/Math.max(1,innerHeight)>=2.7||(size.width<1000&&title.textContent.length>35);host.classList.toggle('holiday-compact',compact);if(host.dataset.compactArt!==String(compact)){host.dataset.compactArt=String(compact);art.innerHTML=compact?'<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="var(--art-main)" stroke-width="1.6"><rect x="4" y="5" width="16" height="16" rx="3"/><path d="M8 2v6M16 2v6M4 11h16M8 15h3M14 15h2"/></svg>':svg(Number(host.dataset.motif)||18);}const date=host.querySelector('#date');if(date&&date.clientWidth){const ctx=document.createElement('canvas').getContext('2d'),cs=getComputedStyle(date),base=parseFloat(getComputedStyle(host).getPropertyValue('--edu-header-title'))*.72||44;ctx.font=[cs.fontWeight,base+'px',cs.fontFamily].join(' ');const needed=ctx.measureText(date.textContent).width;date.style.setProperty('--holiday-date-size',Math.min(base,base*date.clientWidth/Math.max(1,needed)*.96)+'px');}title.style.fontSize='';const hs=getComputedStyle(host),gap=parseFloat(getComputedStyle(title.parentElement).rowGap)||0,other=[label,note].reduce((n,x)=>n+x.getBoundingClientRect().height,0);title.style.maxHeight=Math.max(28,host.clientHeight-(parseFloat(hs.paddingTop)||0)-(parseFloat(hs.paddingBottom)||0)-other-gap*2)+'px';let font=parseFloat(getComputedStyle(title).fontSize);for(let i=0;i<18&&(title.scrollWidth>title.clientWidth+1||title.scrollHeight>title.clientHeight+1)&&font>Math.max(12,unit*.6);i++){font=Math.max(12,unit*.6,font*.9);title.style.fontSize=font+'px';}}
function present(date,data,events,cfg){install();if(!host)return;const currentDate=new Date(date+'T12:00:00'),locale=cfg.country==='sk'?'sk-SK':'cs-CZ';dateDay.textContent=String(currentDate.getDate());dateMonth.textContent=new Intl.DateTimeFormat(locale,{month:'long'}).format(currentDate);dateFoot.textContent=new Intl.DateTimeFormat(locale,{weekday:'long'}).format(currentDate)+' · '+currentDate.getFullYear();datePanel.setAttribute('aria-label',new Intl.DateTimeFormat(locale,{dateStyle:'full'}).format(currentDate));const special=motif(date,data.nameday,events);const commemorative=special===33||[2,3,5,20,22,23,25,28,34].includes(special);const names=data.nameday||'';const main=events.length?events.map(e=>e.name).join(' · '):names;title.textContent=main|| (cfg.country==='sk'?'Dnešný deň':'Dnešní den');label.textContent=events.length||special===33?(commemorative?(cfg.country==='sk'?'Dnešná pripomienka':'Dnešní připomínka'):(cfg.country==='sk'?'Dnešný sviatok':'Dnešní svátek')):(cfg.country==='sk'?'Dnes oslavuje':'Dnes slaví');note.textContent=!events.length&&cfg.tomorrow?document.getElementById('tomorrow')?.textContent||'':'';const id=special||18;art.innerHTML=svg(id);host.dataset.motif=String(id);delete host.dataset.compactArt;const tone=new URLSearchParams(location.search).get('headerTone')||new URLSearchParams(location.search).get('kiosk_header');const light=tone==='light'||(!tone&&cfg.viewMode==='kiosk');host.classList.toggle('holiday-light',light);if(cfg.viewMode==='kiosk')document.documentElement.dataset.kioskHeader=light?'light':'dark';host.style.setProperty('background',light?'var(--ev-surface)':'var(--ev-primary)','important');host.style.setProperty('color',light?'var(--ev-text)':'var(--ev-primary-text)','important');
 const namesCard=document.getElementById('names-card'),holidayCard=document.getElementById('holiday-card');if(holidayCard)holidayCard.classList.add('hidden');if(namesCard&&(!events.length||events.some(e=>e.name===names)))namesCard.classList.add('hidden');requestAnimationFrame(fit);}
root.EduvizeHolidayArt=Object.freeze({motifs,motif,svg,present,fit});
